-- Версия 1.7.0. Требует supabase/sql/site_releases.sql. Повторный запуск безопасен.
-- Применять после деплоя сайта и функции tg-app (check_get, check_delete).
-- Подсказки «А вы знали?» не нужны: новых функций сайта для преподавателей нет (scope app и улучшения).
select public.add_site_release('1.7.0','Проверка работ: новый экран и автоснимок, таблица соответствий в билетах',
  jsonb_build_array(
    jsonb_build_object('kind','new','scope','app','min_rank',1,'text','Проверка работ: камера сама снимает бланк, когда он целиком в рамке, и сразу пишет, прочитан ли он; неудачный снимок можно тут же переснять.'),
    jsonb_build_object('kind','new','scope','app','min_rank',1,'text','Проверка работ: сохранённую работу можно открыть и посмотреть ошибки по заданиям, найти по имени или удалить.'),
    jsonb_build_object('kind','new','scope','app','min_rank',1,'text','Проверка работ: свои ключи сохраняются в вашем Telegram и видны на всех ваших устройствах.'),
    jsonb_build_object('kind','new','scope','app','min_rank',1,'text','Проверка работ: эталонный бланк для своего ключа можно не только сфотографировать, но и выбрать готовое фото из галереи; если на фото бланк другого вида или фото читается плохо, приложение прямо скажет об этом.'),
    jsonb_build_object('kind','improved','scope','app','min_rank',1,'text','Проверка работ: новый экран — балл и кнопка «Сохранить» всегда внизу, ответы сеткой как на бланке, сомнительные места показаны фрагментом снимка, снимок открывается крупно, после сохранения можно отменить.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',1,'text','Билеты классу: в вопросах на соответствие ученик отмечает ответ в таблице A–D на 1–5, как на бумажном бланке.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',1,'text','Билеты классу: если ученик выбрал таджикский язык билета, вся страница — зал ожидания, кнопки, окно сдачи, результат, разбор и предупреждения — тоже на таджикском; при русском билете всё на русском.'),
    jsonb_build_object('kind','improved','scope','site','min_rank',2,'text','Банк вопросов: форма вопроса и импорт больше не принимают открытый вопрос, ответ которого нельзя вписать в клетки бланка, — дробный, с минусом или длиннее клеток (4 цифры, у таджикского и английского языков 5); причина показывается сразу.')
  ),
  '2026-11-25 00:10:00+05');
